export default function validateLibrary(library) {
  if (!library) {
    throw new Error('Library is required');
  }

  if (typeof library !== 'object' || Array.isArray(library)) {
    throw new Error('Library must be an object');
  }

  if (!library.name || !library.version) {
    throw new Error('Library must have name and version');
  }

  return true;
}

import validateLibrary from '../src/library_validation_contract.mjs';

const testLibrary = {
  name: 'example-library',
  version: '1.0.0'
};

const invalidLibrary = {
  version: '1.0.0'
};

const testCases = [
  { input: testLibrary, expected: true },
  { input: invalidLibrary, expected: false }
];

for (const { input, expected } of testCases) {
  const result = validateLibrary(input);
  console.assert(result === expected, `Test failed for input: ${JSON.stringify(input)}`);
}

